/// <summary>
/// This is a task service class
/// CB355_DutyRoll
class METDutyAdValorumClaimGenerateTaskService extends METSysOperationTaskService
{
    METVendClaimDutyRollVarTmp             vendClaimDutyRollVarTmp;
    METDutyRollMonthlyQueue                dutyRollMonthlyQueue;
    guid                                   topPickingProcessId;
    boolean                                dutyBySite;
    boolean                                generateClaim;
    boolean                                filterItemSite;
    METDutyAdValorumClaimGenerateContract  contract;


}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    contract       = dataContract as METDutyAdValorumClaimGenerateContract;
    dutyBySite     = contract.parmDutyValuesBySite();
    generateClaim  = contract.parmGenerateClaims();
    filterItemSite = contract.parmFilterItemSite();

    vendClaimDutyRollVarTmp.useExistingTempDBTable(contract.parmVendClaimDutyRollVarTable());
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METDutyAdValorumClaimGenerateContract</c>.
/// </param>
public void process(METDutyAdValorumClaimGenerateContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Runs tasks of the task service class.
/// </summary>
/// <param name = "_readPast">Table read past setting</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (dutyRollMonthlyQueue.RecId != 0)
            {
                this.execute();
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Gets data from queue table <c>MetDutyRollMonthlyQueue</c>.
///</summary>
/// <param name = "_processId">Guid created and added in the contract <c>METDutyAdValorumClaimGenerateContract</c>.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METDutyRollMonthlyQueue     topPickingQueue;
    int                         backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            //Copies data in dutyRollMonthlyQueue from topPickingQueue buffer.
            dutyRollMonthlyQueue.data(topPickingQueue);

            topPickingQueue.delete();
        }
        else
        {
            ///Empties the table buffer of dutyRollMonthlyQueue.
            DictTable dutyRollMonthlyQueueDictTable = new DictTable(tableNum(METDutyRollMonthlyQueue));
            dutyRollMonthlyQueue = dutyRollMonthlyQueueDictTable.makeRecord();
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (dutyRollMonthlyQueue.RecId != 0);
}

/// <summary>
/// Executes the process.
/// </summary>
private void execute()
{
    METVendClaimProcessHelper   vendClaimProcessHelper;
    METDutyRollVariance         dutyRollVariance;
    METDutyRollVariance         dutyRollVarianceDelete;
    METExciseSiteDutySetup      exciseSiteDutySetup;
    METInventTable              metInventTable;
    METTariffItemCode           tariffItemCode;

    select firstonly dutyRollVariance
        order by CreatedDateTime
            where dutyRollVariance.ItemId == dutyRollMonthlyQueue.ItemId
               && dutyRollVariance.Site == dutyRollMonthlyQueue.SiteId
               && dutyRollVariance.InventTransType == InventTransType::Purch;

    if (dutyBySite || filterItemSite)
    {
        metInventTable = metInventTable::find(dutyRollVariance.ItemId);
        exciseSiteDutySetup = METExciseSiteDutySetup::find(dutyRollVariance.Site, dutyRollVariance.ItemId);

        METDutyRollValuesTable dutyRollValuesTable;
        METDutyRollValuesLine dutyRollValuesLine;

        utcdatetime currentUtcDateTime = DateTimeUtil::getSystemDateTime();//DateTimeUtil::utcNow();

        select firstonly validtimestate(currentUtcDateTime) AverageVFD, TotalDutyPerCase from dutyRollValuesLine
            exists join dutyRollValuesTable
                where dutyRollValuesTable.RecId == dutyRollValuesLine.RefRecId
                   && dutyRollValuesLine.Site == dutyRollMonthlyQueue.SiteId
                   && dutyRollValuesLine.ItemId == dutyRollMonthlyQueue.ItemId
                   && dutyRollValuesTable.Status == METDutyRollStatus::Active;

        exciseSiteDutySetup.ValueForDuty    = dutyRollValuesLine.AverageVFD;
        tariffItemCode  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
        //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))

        exciseSiteDutySetup.DutyTotal   = dutyRollValuesLine.TotalDutyPerCase;
        exciseSiteDutySetup.CalcDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        exciseSiteDutySetup.RunBy       = curUserId();
        if (exciseSiteDutySetup.RecId)
        {
            ttsbegin;
            exciseSiteDutySetup.selectForUpdate(true);
            exciseSiteDutySetup.update();
            ttscommit;
        }
        else
        {
            ttsbegin;
            exciseSiteDutySetup.ItemId  = dutyRollVariance.ItemId;
            exciseSiteDutySetup.SiteId  = dutyRollVariance.Site;
            exciseSiteDutySetup.insert();
            ttscommit;
        }

    }

    if (dutyRollVariance && filterItemSite)
    {
        ttsbegin;
        dutyRollVariance.selectForUpdate(true);
        dutyRollVariance.SiteSpeceificDutyUpdated   = NoYes::Yes;
        dutyRollVariance.ClaimCreated               = NoYes::No;
        dutyRollVariance.update();
        ttscommit;
    }
    else if (dutyBySite && generateClaim && dutyRollVariance.ClaimAmount != 0)
    {
        ttsbegin;

        vendClaimDutyRollVarTmp.clear();
        vendClaimDutyRollVarTmp.DutyRollVarRecId = dutyRollVariance.RecId;

        vendClaimDutyRollVarTmp.insert();

        ttscommit;
    }

}
